SELECT

FROM t_quartz_task t
WHERE 1 = 1

    AND t.id = #{queryDTO.id}


    AND (
        INSTR(t.task_name, #{queryDTO.taskName})
        OR INSTR(t.remark, #{queryDTO.taskName})
    )


    AND t.task_status = #{queryDTO.taskStatus}


    AND t.task_type = #{queryDTO.taskType}


    AND INSTR(t.task_system, #{queryDTO.taskSystem})


    AND INSTR(t.theme, #{queryDTO.theme})

ORDER BY t.id DESC

